const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const art=f=>'assets/archive/original/'+f;
const p=s=>`<p>${esc(s)}</p>`;
const link=(id,text)=>`<a href="guide.html?entry=${encodeURIComponent(id)}">${esc(text)}</a>`;
const eyebrow=s=>`<p class="eyebrow">${esc(s)}</p>`;
const main=$('#main'), dialog=$('#entry-dialog');let D;
$('.menu-toggle').addEventListener('click',e=>{const b=e.currentTarget,open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',open);b.setAttribute('aria-label',open?'Close navigation':'Open navigation');$('.masthead nav').classList.toggle('open',open);});
$('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function entryOpen(id){
 const e=D.entries.find(e=>e.id===id);if(!e)return;
 const values=e.stats?.length?`<dl class="stat-list">${e.stats.map(x=>`<div><dt>${esc(x.label)}</dt><dd>${esc(x.value)}</dd></div>`).join('')}</dl>`:'';
 $('#entry-body').innerHTML=`${eyebrow(e.sourceArea+' · '+(D.categories.find(c=>c.id===e.category)?.title||e.category))}<h2 id="entry-title">${esc(e.title)}</h2><p class="entry-lead">${esc(e.summary)}</p>${e.body.map(p).join('')}${values}${e.warnings.length?`<div class="warning"><h3>Reference notes</h3>${e.warnings.map(p).join('')}</div>`:''}<details class="source-details"><summary>Evidence & source</summary><p>${esc(e.evidenceLabel)} · ${esc(e.date||D.edition)}. “Reviewed” describes a source review, not a new gameplay test.</p><ul>${(e.sources||[]).map(s=>`<li>${esc(typeof s==='string'?s:s.path+(s.line?':'+s.line:'')+(s.record?' · '+s.record:''))}</li>`).join('')}</ul></details>`;
 dialog.showModal();dialog.scrollTop=0;
}
function home(){
 main.innerHTML=`<section class="hero"><img class="hero-image" src="${art('moon_forest.webp')}" alt="A moonlit forest and a towering horned creature, concept artwork"><div class="hero-content wrap">${eyebrow(D.hero.eyebrow)}<h1>The realm<br><em>remembers.</em></h1><p class="lead">${esc(D.hero.description)}</p><div class="hero-actions"><a class="button" href="#world">Discover the realm <span aria-hidden="true">↓</span></a><a class="text-link" href="story.html">Meet its people ↗</a></div></div><div class="hero-foot"><span>Exploration · Relief magic · Consequence</span><span>In development / concept artwork</span></div></section>
 <section class="wrap chapter-intro">${eyebrow('01 / THE WORLD YOU ENTER')}<h2>Survival is only<br><em>the beginning.</em></h2><div><p class="lead">${esc(D.hero.intro)}</p><div class="intro-line"><span>A personal story</span><span>A shared world</span><span>Lasting consequences</span></div></div></section>
 <section class="wrap section" id="world"><div class="section-top"><div>${eyebrow('02 / PLACES & PEOPLE')}<h2>Beyond the<br><em>forest’s edge.</em></h2></div><p>Discover communities with their own loyalties, fears and unfinished stories. No single faction tells the whole truth.</p></div><div class="region-shell" id="region-panel"></div><div class="region-tabs" role="group" aria-label="Explore regions">${D.regions.map((r,i)=>`<button data-region="${i}" aria-pressed="${i===0}"><span>0${i+1}</span>${esc(r.name)}</button>`).join('')}</div></section>
 <section class="combat-section"><div class="wrap section combat-layout"><div>${eyebrow('03 / COMBAT')}<h2>Choose your weapon.<br><em>Know its cost.</em></h2><p class="lead">Timing, positioning and commitment shape a fight. Learn how your weapon behaves, when to defend, and what changes when a technique becomes an Ultimate.</p><div class="hero-actions"><a class="button outline" href="guide.html?category=weapons">Explore combat ↗</a></div></div><div class="combat-list"><a href="guide.html?category=weapons"><span>01</span><div><h3>A weapon with a purpose</h3><p>Passives, signature techniques and learned physical Ultimates.</p></div><span>↗</span></a><a href="guide.html?category=rules"><span>02</span><div><h3>Read the fight</h3><p>Damage, guard, parries, positioning and the exceptions that matter.</p></div><span>↗</span></a><a href="guide.html?category=progression"><span>03</span><div><h3>Build your character</h3><p>Core Traits, perks, progression and the paths beyond a first campaign.</p></div><span>↗</span></a></div></div></section>
 <section class="wrap section" id="magic"><div class="section-top"><div>${eyebrow('04 / RELIEF MAGIC')}<h2>Power made<br><em>physical.</em></h2></div><p>Holy, Blood and Dark magic are expressed through physical Reliefs. Deployment, influence and release are part of casting—not merely its appearance.</p></div><div class="school-tabs" role="group" aria-label="Magic schools">${D.schools.map((s,i)=>`<button data-school="${i}" aria-pressed="${i===0}">${esc(s.id)}</button>`).join('')}</div><div id="school-panel"></div></section>
 <section class="shared-banner"><div>${eyebrow('05 / PLAYING TOGETHER')}<h2>Share the journey.<br><em>Keep your history.</em></h2></div><div><div class="coop-facts"><div><strong>4</strong><span>HUMANS PER CAMPAIGN</span></div><div><strong>2</strong><span>LOCAL PLAYERS PER MACHINE</span></div></div><p>Your choices belong to your character. The host controls the shared physical outcome; your personal answer, relationships and consequences can remain different.</p><p class="small">Documented LAN and direct-address sessions. See the guide for evidence and current limitations.</p><p><a class="text-link" href="guide.html?category=coop">Understand co-op ↗</a></p></div></section>
 <section class="wrap section faq-layout" id="guide"><div>${eyebrow('BEFORE YOU BEGIN')}<h2>A few things<br><em>worth knowing.</em></h2></div><div class="faq-list">${D.faq.map(f=>`<details><summary>${esc(f.q)}</summary>${p(f.a)}</details>`).join('')}</div></section><section class="end-cta">${eyebrow('THE FIELD GUIDE')}<h2>Go a little <em>deeper.</em></h2><a class="button" href="guide.html">Explore ${D.entries.length} guide entries ↗</a></section>`;
 const region=i=>{const r=D.regions[i];$('#region-panel').innerHTML=`<div class="region-visual"><img src="${art(r.image)}" alt="${esc(r.name)} concept artwork" loading="lazy"><span class="art-label">CONCEPT ARTWORK · NOT GAMEPLAY</span></div><div class="region-info reveal">${eyebrow(r.place)}<h3>${esc(r.name)}</h3>${p(r.description)}<div class="region-index">0${i+1} <span>—</span> 0${D.regions.length}</div></div>`;$$('[data-region]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.region)===i));};
 const school=i=>{const s=D.schools[i],spells=D.entries.filter(e=>e.school===s.id);$('#school-panel').innerHTML=`<div class="school-layout reveal"><div class="school-art"><img src="${esc(s.image)}" alt="${esc(s.id)} Relief inscription reference" loading="lazy"><span class="art-label">RELIEF INSCRIPTION REFERENCE</span></div><div>${eyebrow(s.id+' RELIEF')}<h3>${esc(s.line)}</h3><p class="muted">${esc(s.description)}</p><div class="spell-list">${spells.map(e=>link(e.id,e.title)).join('')}</div><a class="text-link" href="guide.html?school=${s.id}">Read the ${esc(s.id)} spellbook ↗</a></div></div>`;$$('[data-school]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.school)===i));};
 $$('[data-region]').forEach(b=>b.addEventListener('click',()=>region(Number(b.dataset.region))));$$('[data-school]').forEach(b=>b.addEventListener('click',()=>school(Number(b.dataset.school))));region(0);school(0);
}
function guide(){
 const params=new URLSearchParams(location.search);let category=params.get('category')||'all',school=params.get('school')||'',query='',limit=30;
 if(!D.categories.some(c=>c.id===category))category='all';
 main.innerHTML=`<div class="wrap page-heading">${eyebrow('THE PLAYER GUIDE')}<h1>Know the rules.<br><em>Find your way.</em></h1><p class="lead">Combat, magic, travel and the consequences of your choices. Search the current reference drawn from the Development Bible.</p></div><div class="guide-toolbar wrap"><div class="search-row"><div class="search-wrap"><label class="small" for="guide-search">Search the guide</label><input id="guide-search" type="search" autocomplete="off" placeholder="Try Void Stasis, fast travel, parry…"></div><span id="result-count" class="result-count" aria-live="polite"></span></div><div class="filters" aria-label="Guide categories"><button data-category="all" aria-pressed="true">Everything</button>${D.categories.map(c=>`<button data-category="${esc(c.id)}" aria-pressed="false">${esc(c.title)}</button>`).join('')}</div><div class="filters" aria-label="Magic schools"><button data-magic="" aria-pressed="${!school}">All schools</button>${D.schools.map(s=>`<button data-magic="${s.id}" aria-pressed="${school===s.id}">${s.id}</button>`).join('')}</div></div><div class="wrap"><div id="guide-grid" class="guide-grid"></div><button id="load-more" class="load-more">Show more entries ↓</button><p class="guide-note"><strong>Read the evidence with the entry.</strong> The Bible’s reviewed Combat catalog takes priority over older Atlas descriptions. Other systems retain their reference notes and limitations. These pages do not certify a release build. <a class="text-link" href="updates.html">Source & updates ↗</a></p></div>`;
 const render=()=>{const words=query.toLowerCase().trim().split(/\s+/).filter(Boolean);const results=D.entries.filter(e=>(category==='all'||e.category===category)&&(!school||e.school===school)&&words.every(w=>[e.title,e.summary,...e.body,...e.tags].join(' ').toLowerCase().includes(w)));$('#result-count').textContent=results.length+' '+(results.length===1?'entry':'entries');$('#guide-grid').innerHTML=results.length?results.slice(0,limit).map(e=>`<button class="guide-card" data-entry="${esc(e.id)}">${eyebrow(D.categories.find(c=>c.id===e.category)?.title||e.category)}<h2>${esc(e.title)}</h2>${p(e.summary)}<span class="card-bottom"><span>${esc(e.evidenceLabel)}</span><span aria-hidden="true">↗</span></span></button>`).join(''):'<div class="empty"><h2>No matching entries</h2><p>Try another term or clear the filters.</p><button class="button outline" id="reset-search">Clear search & filters</button></div>';$('#load-more').hidden=results.length<=limit;$$('[data-category]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.category===category));$$('[data-magic]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.magic===school));$$('[data-entry]').forEach(b=>b.addEventListener('click',()=>entryOpen(b.dataset.entry)));$('#reset-search')?.addEventListener('click',()=>{query='';category='all';school='';$('#guide-search').value='';render();});};
 $('#guide-search').addEventListener('input',e=>{query=e.target.value;limit=30;render();});$$('[data-category]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;limit=30;render();}));$$('[data-magic]').forEach(b=>b.addEventListener('click',()=>{school=b.dataset.magic;if(school)category='reliefs';limit=30;render();}));$('#load-more').addEventListener('click',()=>{limit+=30;render();});render();if(params.has('entry'))entryOpen(params.get('entry'));
}
function story(){
 main.innerHTML=`<div class="wrap page-heading">${eyebrow('STORY & PEOPLE')}<h1>Every answer<br><em>leaves a trace.</em></h1><p class="lead">Your response is part of the story—even when you cannot change what happens. Meet the people behind the choices, then decide how much you want to know.</p></div><section class="story-splash"><img src="${art('doll_relief.webp')}" alt="The Cursed Doll and a Relief, concept artwork"><div>${eyebrow('THE FIRST VOICE')}<h2>Help is not<br><em>the same as trust.</em></h2><p class="muted">A voice reaches you beneath the old house. The Doll can guide you, but the meaning of that guidance is part of the journey.</p><p class="small">Concept artwork · The story and gameplay remain in development.</p></div></section><div class="spoiler-control"><label><input type="checkbox" id="spoilers">Reveal story spoilers</label><p>Reveals character truths, quest names, the five moral decisions and the ending rules. Spoilers start off every time you open this page.</p></div><section class="wrap section"><div class="section-top"><div>${eyebrow('THE PEOPLE YOU MEET')}<h2>Lives beyond<br><em>your own.</em></h2></div><p>Relationships are individual. A family, faction or title does not make everyone’s history—or judgment of you—the same.</p></div><div class="character-grid" id="characters"></div></section><div class="wrap" id="story-detail"></div>`;
 const render=()=>{const shown=$('#spoilers').checked;$('#characters').innerHTML=D.characters.map(c=>`<article class="character">${eyebrow(c.role)}<h3>${esc(c.name)}</h3>${p(c.intro)}${shown?`<details><summary>Read the character’s story</summary>${p(c.detail)}</details>`:''}</article>`).join('');
 if(!shown){$('#story-detail').innerHTML='<div class="spoiler-hidden"><h3>The rest is yours to discover.</h3><p>Enable story spoilers above to explore moral decisions, current quests and the endings.</p></div>';return;}
 $('#story-detail').innerHTML=`<section class="section"><div class="section-top"><div>${eyebrow('SPOILERS / YOUR MORAL HISTORY')}<h2>Five decisions.<br><em>Your own answers.</em></h2></div><p>The counts of your recorded Good and Evil answers determine your route after six distinct demons. Karma, reputation and personality-style points are different systems.</p></div><div class="route-grid"><div id="choice-list">${D.decisions.map(d=>`<div class="choice-row" data-choice-row="${d.id}">${eyebrow(d.id)}<h3>${esc(d.title)}</h3>${p(d.setup)}<div class="choice-buttons"><button data-choice="${d.id}" data-value="Good" aria-pressed="false">${esc(d.good)}</button><button data-choice="${d.id}" data-value="Evil" aria-pressed="false">${esc(d.evil)}</button><button data-choice="${d.id}" data-value="" aria-pressed="true">Unanswered</button></div><details class="source-details"><summary>What happens</summary>${p(d.consequence)}${p(d.after)}</details></div>`).join('')}<div class="route-controls"><label>Creator inclination<select id="inclination"><option>Unwritten</option><option>Benevolent</option><option>Malevolent</option></select></label><label>Distinct demons defeated<select id="demons">${[0,1,2,3,4,5,6].map(n=>`<option${n===6?' selected':''}>${n}</option>`).join('')}</select></label></div><p class="small" style="margin-top:20px">A reading aid based on the Bible’s rule. It does not change a character, save or game state.</p></div><aside class="route-output" id="route-output" aria-live="polite"></aside></div></section><section class="section"><div class="section-top"><div>${eyebrow('SPOILERS / THE FINAL BATTLE')}<h2>A route is not<br><em>a guaranteed ending.</em></h2></div><p>Final-battle side switching remains possible and does not rewrite earlier moral answers. Victory and survival matter.</p></div><div class="ending-grid"><article class="ending-card">${eyebrow('KINGDOM ROUTE / WIN ON THE KINGDOM SIDE')}<h3>The Demon Father Is No More</h3><p>Defeat the Demon Father. The realm is freed from his immediate threat.</p></article><article class="ending-card">${eyebrow('CULT ROUTE / WIN WITH THE CULT')}<h3>The Kingdom Is Fallen</h3><p>The Kingdom falls. Lucan escapes with the King and Queen through his Blood shield; their deaths are not this ending.</p></article><article class="ending-card">${eyebrow('CULT ROUTE / SWITCH TO THE KINGDOM AND WIN')}<h3>The Invasion Is Repelled</h3><p>The Cult’s invasion fails and the Kingdom endures.</p></article><article class="ending-card">${eyebrow('KINGDOM ROUTE / SWITCH TO THE CULT AND WIN')}<h3>The Demon Father Is Victorious</h3><p>The Demon Father prevails and the Cult rises.</p></article></div><p class="guide-note" style="margin-top:25px"><strong>Co-op has separate outcomes.</strong> An opposing guest victory without the host does not complete the host campaign. The host returns to the pre-battle checkpoint. Personal next-game unlocks depend on surviving on the winning side.</p></section><section class="section" id="quests"><div class="section-top"><div>${eyebrow('SPOILERS / THE QUEST JOURNAL')}<h2>Stories of<br><em>the realm.</em></h2></div><p>Current quest names and summaries from the Bible. Stable internal IDs remain in the source notes when a displayed title changes.</p></div><label class="small" for="quest-search">Search ${D.quests.length} current quest records</label><input class="quest-search" id="quest-search" type="search" placeholder="Search a quest or a place…"><p id="quest-count" class="small" aria-live="polite"></p><div id="quest-list" class="quest-list"></div></section>`;
 const answers={};const updateRoute=()=>{const a=D.alignment;const votes=a.ids.map(id=>answers[id]).filter(Boolean),good=votes.filter(v=>v==='Good').length,evil=votes.filter(v=>v==='Evil').length,inc=$('#inclination').value,demons=Number($('#demons').value);let route=null,reason='';if(demons<6)reason='Defeat six distinct demons before the route locks.';else if(!answers[a.first])reason='Answer the hanging decision first. If missed, the game asks before selecting a route.';else if(good>evil){route='Kingdom';reason='Your recorded Good answers are the majority.';}else if(evil>good){route='Cult';reason='Your recorded Evil answers are the majority.';}else if(inc==='Benevolent'){route='Kingdom';reason='The tied count uses your Benevolent creator inclination.';}else if(inc==='Malevolent'){route='Cult';reason='The tied count uses your Malevolent creator inclination.';}else reason='A tied Unwritten character uses one saved random result in the game. This guide does not invent that result.';const q=D.quests.find(q=>q.id===(route==='Kingdom'?'Q07H_NoMoreOfferings':'Q07E_LetTheKingdomAnswer'));$('#route-output').innerHTML=`${eyebrow(good+' GOOD · '+evil+' EVIL')}<h3>${route?(route==='Kingdom'?'Good ending route':'Evil ending route'):'Your route is not decided'}</h3>${route?`<p><strong>${esc(route)} · ${esc(q?.title||'')}</strong></p>`:''}${p(reason)}${route?'<p>Stay on that side and win to reach its ending. You may still switch sides during the final battle.</p>':''}`;$$('[data-choice]').forEach(b=>b.setAttribute('aria-pressed',(answers[b.dataset.choice]||'')===b.dataset.value));};
 $$('[data-choice]').forEach(b=>b.addEventListener('click',()=>{answers[b.dataset.choice]=b.dataset.value;updateRoute();}));$('#inclination').addEventListener('change',updateRoute);$('#demons').addEventListener('change',updateRoute);updateRoute();
 const renderQuests=()=>{const q=$('#quest-search').value.toLowerCase(),rows=D.quests.filter(x=>[x.title,x.description,x.group].join(' ').toLowerCase().includes(q));$('#quest-count').textContent=rows.length+' '+(rows.length===1?'quest':'quests');$('#quest-list').innerHTML=rows.length?rows.map(x=>`<details><summary>${esc(x.title)}</summary>${p(x.description)}<small>${esc(x.group)} · ${esc(x.id)}<br>${esc(x.source)}</small></details>`).join(''):'<p class="empty">No quests match this search.</p>';};$('#quest-search').addEventListener('input',renderQuests);renderQuests();};
 $('#spoilers').addEventListener('change',render);render();
}
function updates(){
 main.innerHTML=`<div class="wrap page-heading">${eyebrow('SOURCE & UPDATES')}<h1>One source.<br><em>A clearer story.</em></h1><p class="lead">The Development Bible takes priority over every earlier version of this website. Its current project records and canon corrections guide this edition.</p></div><div class="wrap"><section class="source-panel"><h2>The Development Bible edition</h2><p>This website draws from the Bible’s reviewed combat catalog, current quest snapshot, character canon and selected Atlas systems. It carries forward ${D.coverage.combat} combat entries, ${D.coverage.systems} additional player systems and ${D.coverage.quests} quest records.</p><p>Edition: ${esc(D.edition)}. Canonical source revision: <code>${esc(D.sourceDigest.slice(0,16))}</code>. <a class="text-link" href="sync-status.json">View the edition record ↗</a></p><p>Illustrations retained from the earlier website are labelled concept artwork or visual reference. They are not presented as current gameplay captures.</p></section><div class="spoiler-control"><label><input type="checkbox" id="review-spoilers">Reveal the comparison and story spoilers</label><p>The comparison includes character identities, quest names and ending details.</p></div><div id="review-content" hidden><section class="section" style="padding-top:20px"><div class="section-top"><div>${eyebrow('THE RECONCILIATION')}<h2>What changed<br><em>and why.</em></h2></div><p>These decisions replace the earlier merge policy. Where the Bible itself contains an older statement, its newer canon and explicit comparison findings take priority.</p></div><div class="audit-grid">${D.audit.map(a=>`<article class="audit-entry"><h2>${esc(a.topic)}</h2><div><strong>Earlier website</strong>${p(a.before)}</div><div class="now"><strong>Development Bible edition</strong>${p(a.now)}</div></article>`).join('')}</div></section><section class="section" style="padding-top:20px"><h2>Still <em>unresolved.</em></h2><ul class="review-list">${D.unresolved.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><details class="source-details"><summary>Discrepancies recorded inside the Bible’s Atlas</summary>${D.sourceFindings.map(f=>`<h3>${esc(f.title)}</h3>${p(f.project)}`).join('')}</details></section></div></div>`;
 $('#review-spoilers').addEventListener('change',e=>{$('#review-content').hidden=!e.target.checked;});
}
try{const response=await fetch('site-data.json');if(!response.ok)throw Error('The guide data could not be loaded.');D=await response.json();$('#edition').textContent='Development Bible edition · '+D.edition;({home,guide,story,updates}[document.body.dataset.view]||home)();}catch(e){main.innerHTML='<div class="wrap page-heading"><h1>The realm is<br><em>temporarily quiet.</em></h1><p class="lead">The guide could not load. Please refresh to try again.</p><p class="small">'+esc(e.message)+'</p></div>';}
